Method.Source:
/// <summary>
/// Runs a script for callers without a browser, such as the form tools of the Dynamics 365 ERP MCP server: they set
/// Script, or the ID of a saved script, click Execute and read the infolog in the reply of that click.
/// The script editor stays as it is.
/// </summary>
[Form]
public class MXTAgentMCPExecute extends FormRun
{
}

/// <summary>
/// Both fields are emptied first, so a click without a new script can't run an old one. The security check and the
/// execution log are the ones of the script editor: both run through MXTXppInterpreterExecutor::execute.
/// Status says whether the script ran to its end, and Result holds what it returned.
/// </summary>
public void runScript()
{
    str source = Script.text();
    RecId savedScriptId = ScriptId.value();

    Script.text('');
    ScriptId.value(0);
    Status.selection(MXTXppInterpreterExecutionStatus::NotRun);
    Result.text('');

    MXTXppInterpreterScriptExecutionLog::checkSecurityRights();

    if (source && savedScriptId)
    {
        error("@MXT:AgentScriptOrId");
        return;
    }

    if (!source && !savedScriptId)
    {
        error("@MXT:AgentScriptEmpty");
        return;
    }

    MXTXppInterpreterScript savedScript;

    if (savedScriptId)
    {
        savedScript = MXTXppInterpreterScript::find(savedScriptId);

        if (!savedScript)
        {
            error(strFmt("@MXT:AgentScriptNotFound", savedScriptId));
            return;
        }
    }

    MXTXppInterpreterExecutionResult executionResult;
    System.Exception ex;

    try
    {
        // A saved script runs as Execute now of the workspace does: with its dependencies
        executionResult = savedScript
            ? MXTXppInterpreterExecutor::executeScript(savedScript, MXTXppInterpreterParameters::find())
            : MXTXppInterpreterExecutor::execute(source);
    }
    catch (Exception::Error)
    {
        Status.selection(MXTXppInterpreterExecutionStatus::Failed);
        return;
    }
    catch (ex)
    {
        // As in the script editor: only an X++ error is in the infolog already
        error(ex.ToString());
        Status.selection(MXTXppInterpreterExecutionStatus::Failed);
        return;
    }

    ListEnumerator parseErrors = executionResult.parseErrors().getEnumerator();

    while (parseErrors.moveNext())
    {
        error(parseErrors.current());
    }

    if (executionResult.hasRun())
    {
        Status.selection(MXTXppInterpreterExecutionStatus::Succeeded);
        Result.text(executionResult.returnValueText());
    }
}
